/bin/zsh -c "python3 - <<'PY'
from pathlib import Path
p=Path('proof.md').read_text()
print('Display delimiters:',p.count('\\\\['),p.count('\\\\]'))
print('Inline delimiters:',p.count('\\\\('),p.count('\\\\)'))
stack=[]
for i,line in enumerate(p.splitlines(),1):
    if '\\\\[' in line:
        stack.append(i)
    if '\\\\]' in line:
        if stack:stack.pop()
        else:print('Unmatched close',i)
print('Unclosed display starts',stack)
PY
sed -n '325,365p' proof.md"

